import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long budget = nextLong();
        long[] tp = new long[n], cost = new long[n];
        for (int i = 0; i < n; i++) tp[i] = nextLong();
        for (int i = 0; i < n; i++) cost[i] = nextLong();
        long lo = Long.MAX_VALUE, hi = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            if (tp[i] == 0) { System.out.println(0); return; }
            lo = Math.min(lo, tp[i]);
            hi = Math.min(hi, tp[i] * (1 + budget / cost[i]));
        }
        while (lo < hi) {
            long mid = lo + (hi - lo + 1) / 2, left = budget;
            boolean ok = true;
            for (int i = 0; i < n && ok; i++) {
                long need = (mid + tp[i] - 1) / tp[i] - 1;
                if (need <= 0) continue;
                // need * cost > left, checked without overflow
                if (need > left / cost[i]) ok = false;
                else left -= need * cost[i];
            }
            if (ok) lo = mid; else hi = mid - 1;
        }
        System.out.println(lo);
    }
}

