import (
	"bufio"
	"fmt"
	"math"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, budget := readInt(), readInt()
	tp := make([]int, n)
	cost := make([]int, n)
	for i := range tp {
		tp[i] = readInt()
	}
	for i := range cost {
		cost[i] = readInt()
	}
	lo, hi := math.MaxInt64, math.MaxInt64
	for i := 0; i < n; i++ {
		if tp[i] == 0 {
			fmt.Println(0)
			return
		}
		lo = min(lo, tp[i])
		hi = min(hi, tp[i]*(1+budget/cost[i]))
	}
	for lo < hi {
		mid, left, ok := lo+(hi-lo+1)/2, budget, true
		for i := 0; i < n && ok; i++ {
			need := (mid+tp[i]-1)/tp[i] - 1
			if need <= 0 {
				continue
			}
			// need * cost > left, checked without overflow
			if need > left/cost[i] {
